findings.repair:
abbrev word (n : Nat) [NeZero n] := BitVec n

def n2w {n : Nat} [NeZero n] (k : Nat) : word n := BitVec.ofNat n k

def w2n {n : Nat} [NeZero n] (w : word n) : Nat := w.toNat

def FCP {n : Nat} [NeZero n] (f : Nat → Prop) : word n := BitVec.ofNat n (FCP_bits n f)

def v2w {n : Nat} [NeZero n] (v : bitstring) : word n := FCP (fun i => testbit i v)
